246	    private IdempotencyService.Stored doIngestReading(long zoneId, IngestReadingRequest request) {
247	        ZoneRow zone = repository.findZoneByIdForUpdate(zoneId).orElseThrow(
248	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
249	
250	        // 归档为终态：归档时刻之前（含）的迟到位移只记迟到事件，不进入速率曲线。
251	        var archived = repository.findLatestArchivedChainByZone(zoneId);
252	        if (archived.isPresent() && !request.measuredAt().isAfter(archived.get().archivedAt())) {
253	            repository.insertLateEvent(zoneId, archived.get().id(), request.measuredAt(),
254	                    request.displacementMm(), "ARCHIVED_LATE_DATA");
255	            return json(201, new ReadingResponse(null, false, true, null, null,
256	                    "NONE", null, zone.status()));
257	        }
258	
259	        // 监测数据按“测区＋时刻”去重。
260	        var duplicated = repository.findReading(zoneId, request.measuredAt());
261	        if (duplicated.isPresent()) {
262	            ReadingRow existing = duplicated.get();
263	            return json(200, new ReadingResponse(existing.id(), true, false,
264	                    existing.hourlyRate(), existing.dailyRate(), "NONE", null, zone.status()));
265	        }
266	
267	        repository.insertReading(zoneId, request.measuredAt(), request.displacementMm());
268	        recomputeZoneRates(zoneId);
269	        ReadingRow reading = repository.findReading(zoneId, request.measuredAt()).orElseThrow();
270	
271	        String evaluation = evaluateAlarm(zone, reading);
272	        Long chainId = repository.findExecutingChainByZone(zoneId).map(ChainRow::id).orElse(null);
273	        ZoneRow current = repository.findZoneById(zoneId).orElseThrow();
274	        return json(201, new ReadingResponse(reading.id(), false, false,
275	                reading.hourlyRate(), reading.dailyRate(), evaluation, chainId, current.status()));
276	    }
