278	    /**
279	     * 预警分级：日速率严格超过报警值触发红色预警并立即停产撤人；
280	     * 小时速率严格超过预警值触发黄色预警；恰等阈值判正常。
281	     * 红色链执行中（已停产）的后续读数属于回落监测，不再重复受理预警；
282	     * 黄色链执行中再触发黄色视为并发重复预警，拒绝受理（409）。
283	     */
284	    private String evaluateAlarm(ZoneRow zone, ReadingRow reading) {
285	        boolean red = reading.dailyRate() != null && reading.dailyRate() > zone.alarmDailyRate();
286	        boolean yellow = reading.hourlyRate() != null && reading.hourlyRate() > zone.warnHourlyRate();
287	        var executing = repository.findExecutingChainByZone(zone.id());
288	        if (executing.isEmpty()) {
289	            if (red) {
290	                repository.insertChain(zone.id(), LEVEL_RED, CHAIN_EXECUTING, reading.measuredAt(),
291	                        reading.measuredAt().plusMinutes(EVACUATION_LIMIT_MINUTES));
292	                repository.updateZoneStatus(zone.id(), STATUS_STOPPED);
293	                return "RED_CHAIN_CREATED";
294	            }
295	            if (yellow) {
296	                repository.insertChain(zone.id(), LEVEL_YELLOW, CHAIN_EXECUTING, reading.measuredAt(), null);
297	                return "YELLOW_CHAIN_CREATED";
298	            }
299	            return "NORMAL";
300	        }
301	        ChainRow chain = executing.get();
302	        if (LEVEL_RED.equals(chain.level())) {
303	            return "RED_CHAIN_ACTIVE";
304	        }
305	        if (red) {
306	            repository.upgradeChainToRed(chain.id(), reading.measuredAt(),
307	                    reading.measuredAt().plusMinutes(EVACUATION_LIMIT_MINUTES));
308	            repository.updateZoneStatus(zone.id(), STATUS_STOPPED);
309	            return "CHAIN_UPGRADED_RED";
310	        }
311	        if (yellow) {
312	            throw ApiException.conflict("CHAIN_ALREADY_EXECUTING",
313	                    "测区已存在执行中处置链，本次预警不予受理: chainId=" + chain.id());
314	        }
315	        return "NORMAL";
316	    }
