318	    private IdempotencyService.Stored doConfirmEvacuation(long chainId, EvacuationConfirmRequest request) {
319	        ChainRow chain = lockZoneAndChain(chainId);
320	        if (!CHAIN_EXECUTING.equals(chain.status())) {
321	            throw ApiException.conflict("CHAIN_NOT_EXECUTING", "处置链不在执行中，无法确认撤人: " + chainId);
322	        }
323	        if (!LEVEL_RED.equals(chain.level())) {
324	            throw ApiException.unprocessable("NOT_RED_CHAIN", "黄色预警无需停产撤人: " + chainId);
325	        }
326	        if (chain.evacuatedAt() != null) {
327	            throw ApiException.conflict("EVACUATION_ALREADY_CONFIRMED", "撤人已确认: " + chainId);
328	        }
329	        ZoneRow zone = repository.findZoneById(chain.zoneId()).orElseThrow();
330	        // 恰满30分钟判定为按时：仅严格晚于截止时刻才判超时。
331	        if (request.confirmedAt().isAfter(chain.evacuateDeadline())) {
332	            throw ApiException.unprocessable("EVACUATION_TIMEOUT",
333	                    "撤人确认超过30分钟时限: deadline=" + chain.evacuateDeadline());
334	        }
335	        if (request.arrivedCount() != zone.personnelTotal()) {
336	            throw ApiException.unprocessable("PERSONNEL_INCOMPLETE",
337	                    "撤人未全员到位: arrived=" + request.arrivedCount()
338	                            + ", required=" + zone.personnelTotal());
339	        }
340	        // 撤人确认与作业封锁在同一事务内完成。
341	        long confirmationId = repository.insertEvacuation(chainId, chain.zoneId(),
342	                request.confirmedAt(), request.arrivedCount(), true);
343	        repository.markChainEvacuated(chainId, request.confirmedAt());
344	        repository.updateZoneStatus(chain.zoneId(), STATUS_LOCKED);
345	        return json(201, new EvacuationConfirmResponse(confirmationId, chainId, true, STATUS_LOCKED));
346	    }
347	
348	    private IdempotencyService.Stored doApplyResumption(long chainId, ResumptionApplyRequest request) {
349	        ChainRow chain = lockZoneAndChain(chainId);
350	        if (!CHAIN_EXECUTING.equals(chain.status())) {
351	            throw ApiException.conflict("CHAIN_NOT_EXECUTING", "处置链不在执行中，无法申请复工: " + chainId);
352	        }
353	        if (!LEVEL_RED.equals(chain.level())) {
354	            throw ApiException.unprocessable("NOT_RED_CHAIN", "黄色预警无需复工评估: " + chainId);
355	        }
356	        if (chain.evacuatedAt() == null) {
357	            throw ApiException.unprocessable("EVACUATION_NOT_CONFIRMED", "撤人未确认，无法申请复工: " + chainId);
358	        }
359	        repository.findAssessmentByChain(chainId).ifPresent(existing -> {
360	            throw ApiException.conflict("ASSESSMENT_EXISTS", "复工评估已申请: " + chainId);
361	        });
362	        ZoneRow zone = repository.findZoneById(chain.zoneId()).orElseThrow();
363	        // 恰满24小时允许申请：仅严格早于触发后24小时才拒绝。
364	        LocalDateTime earliest = chain.triggeredAt().plusHours(RECOVERY_WINDOW_HOURS);
365	        if (request.appliedAt().isBefore(earliest)) {
366	            throw ApiException.unprocessable("RECOVERY_WINDOW_TOO_SHORT",
367	                    "红色预警后未满24小时，无法申请复工: earliest=" + earliest);
368	        }
369	        // 连续24小时安全判定：按每个时刻实际有效的阈值（策略版本+雨量折减）。
370	        SafetyEvaluation evaluation = evaluateResumptionSafety(chain, zone, request.appliedAt());
371	        long assessmentId = repository.insertAssessment(chainId, chain.zoneId(), request.appliedAt());
372	        insertEvidence(chainId, assessmentId, chain.zoneId(), request.appliedAt(), evaluation);
373	        return json(201, new ResumptionApplyResponse(assessmentId, ASSESSMENT_APPLIED));
374	    }
375	
376	    private IdempotencyService.Stored doConfirmResumption(long chainId, ResumptionConfirmRequest request) {
377	        ChainRow chain = lockZoneAndChain(chainId);
378	        AssessmentRow assessment = repository.findAssessmentByChainForUpdate(chainId).orElseThrow(
379	                () -> ApiException.conflict("ASSESSMENT_NOT_APPLIED", "复工评估未申请: " + chainId));
380	        if (ASSESSMENT_APPROVED.equals(assessment.status())) {
381	            throw ApiException.conflict("RESUMPTION_ALREADY_APPROVED", "复工已批准: " + chainId);
382	        }
383	        String type = request.type();
384	        if (!CONFIRM_SITE_CHECK.equals(type) && !CONFIRM_MONITORING_REVIEW.equals(type)) {
385	            throw ApiException.badRequest("UNKNOWN_CONFIRM_TYPE",
386	                    "确认类型须为SITE_CHECK或MONITORING_REVIEW: " + type);
387	        }
388	        boolean siteCheck = assessment.siteCheckConfirmed();
389	        boolean monitoringReview = assessment.monitoringReviewConfirmed();
390	        if (CONFIRM_SITE_CHECK.equals(type)) {
391	            if (siteCheck) {
392	                throw ApiException.conflict("CONFIRM_DUPLICATED", "现场核查已确认: " + chainId);
393	            }
394	            siteCheck = true;
395	        } else {
396	            if (monitoringReview) {
397	                throw ApiException.conflict("CONFIRM_DUPLICATED", "监测复核已确认: " + chainId);
398	            }
399	            monitoringReview = true;
400	        }
401	        // 双确认齐全才批准复工：停产与复工形成唯一终态。
402	        boolean approved = siteCheck && monitoringReview;
403	        String assessmentStatus = approved ? ASSESSMENT_APPROVED : ASSESSMENT_APPLIED;
404	        if (approved) {
405	            // 批准前按当前快照复评安全条件并冻结证据：雨量更正或策略发布与复工确认
406	            // 并发时，测区行锁保证二者串行，批准所依据的证据与最终数据一致。
407	            ZoneRow zone = repository.findZoneById(chain.zoneId()).orElseThrow();
408	            SafetyEvaluation evaluation = evaluateResumptionSafety(chain, zone, request.confirmedAt());
409	            insertEvidence(chainId, assessment.id(), chain.zoneId(), request.confirmedAt(), evaluation);
410	        }
411	        repository.updateAssessmentConfirmation(assessment.id(), siteCheck, monitoringReview,
412	                assessmentStatus, approved ? request.confirmedAt() : null);
413	        String chainStatus = chain.status();
414	        String zoneStatus = repository.findZoneById(chain.zoneId()).orElseThrow().status();
415	        if (approved) {
416	            repository.updateChainStatus(chainId, CHAIN_RESUMED, null);
417	            repository.updateZoneStatus(chain.zoneId(), STATUS_NORMAL);
418	            chainStatus = CHAIN_RESUMED;
419	            zoneStatus = STATUS_NORMAL;
420	        }
421	        return json(201, new ResumptionConfirmResponse(assessment.id(), siteCheck, monitoringReview,
422	                assessmentStatus, chainStatus, zoneStatus));
423	    }
424	
425	    private IdempotencyService.Stored doArchiveChain(long chainId, ArchiveRequest request) {
426	        ChainRow chain = lockZoneAndChain(chainId);
427	        if (CHAIN_ARCHIVED.equals(chain.status())) {
428	            // 归档为终态：重复归档返回幂等成功。
429	            return json(200, new ArchiveResponse(chainId, CHAIN_ARCHIVED, chain.archivedAt()));
430	        }
431	        if (CHAIN_EXECUTING.equals(chain.status()) && LEVEL_RED.equals(chain.level())) {
432	            throw ApiException.conflict("CHAIN_NOT_RESUMED", "红色处置链须复工批准后方可归档: " + chainId);
433	        }
434	        repository.updateChainStatus(chainId, CHAIN_ARCHIVED, request.archivedAt());
435	        return json(200, new ArchiveResponse(chainId, CHAIN_ARCHIVED, request.archivedAt()));
436	    }
437	
438	    /**
439	     * 按“测区行锁→处置链行锁”顺序加锁并返回最新链状态。
440	     */
441	    private ChainRow lockZoneAndChain(long chainId) {
442	        ChainRow probe = repository.findChainById(chainId).orElseThrow(
443	                () -> ApiException.notFound("CHAIN_NOT_FOUND", "处置链不存在: " + chainId));
444	        repository.findZoneByIdForUpdate(probe.zoneId()).orElseThrow(
445	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + probe.zoneId()));
446	        return repository.findChainByIdForUpdate(chainId).orElseThrow();
447	    }
448	
449	    /**
450	     * 乱序归位后整链复算：按监测时刻重排全部读数并重算速率，保证曲线可复算。
451	     */
452	    private void recomputeZoneRates(long zoneId) {
453	        List<ReadingRow> readings = repository.findReadingsByZone(zoneId);
454	        List<RateCalculator.Sample> samples = readings.stream()
455	                .map(row -> new RateCalculator.Sample(row.measuredAt(), row.displacementMm()))
456	                .toList();
457	        List<RateCalculator.Rated> rated = RateCalculator.compute(samples);
458	        for (int i = 0; i < readings.size(); i++) {
459	            repository.updateReadingRates(readings.get(i).id(),
460	                    rated.get(i).hourlyRate(), rated.get(i).dailyRate());
461	        }
462	    }
463	
464	    private IdempotencyService.Stored json(int status, Object body) {
465	        try {
466	            return new IdempotencyService.Stored(status, objectMapper.writeValueAsString(body));
467	        } catch (Exception e) {
468	            throw new IllegalStateException("响应报文序列化失败", e);
469	        }
470	    }
471	
472	    private IdempotencyService.Stored doPublishStrategy(long zoneId, PublishStrategyRequest request) {
473	        // 与复工确认等同测区写操作共用测区行锁，保证同一快照内判定。
474	        repository.findZoneByIdForUpdate(zoneId).orElseThrow(
475	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
476	        requireFinite(request.yellowRate(), "yellowRate");
477	        requireFinite(request.redRate(), "redRate");
478	        requireFinite(request.rainfall24hThreshold(), "rainfall24hThreshold");
479	        requireFinite(request.reductionFactor(), "reductionFactor");
480	        if (request.yellowRate() >= request.redRate()) {
481	            throw ApiException.unprocessable("THRESHOLD_ORDER_INVALID",
482	                    "基础速率阈值须满足0<黄<红: yellow=" + request.yellowRate()
483	                            + ", red=" + request.redRate());
484	        }
485	        if (request.effectiveFrom().isBefore(request.submittedAt())) {
486	            throw ApiException.unprocessable("EFFECTIVE_BEFORE_SUBMISSION",
487	                    "策略生效时刻不得早于提交时刻: effectiveFrom=" + request.effectiveFrom()
488	                            + ", submittedAt=" + request.submittedAt());
489	        }
490	        int current = repository.findLatestStrategyByZone(zoneId).map(StrategyRow::version).orElse(0);
491	        if (request.expectedVersion() != current) {
492	            throw ApiException.conflict("VERSION_CONFLICT",
493	                    "策略版本冲突: expected=" + request.expectedVersion() + ", current=" + current);
494	        }
495	        int newVersion = current + 1;
496	        long strategyId = repository.insertStrategy(zoneId, newVersion, request.yellowRate(),
497	                request.redRate(), request.rainfall24hThreshold(), request.reductionFactor(),
498	                request.effectiveFrom(), request.submittedAt());
499	        return json(201, new StrategyResponse(strategyId, zoneId, newVersion, request.yellowRate(),
500	                request.redRate(), request.rainfall24hThreshold(), request.reductionFactor(),
501	                request.effectiveFrom(), request.submittedAt()));
502	    }
503	
504	    private IdempotencyService.Stored doReportRainfall(long zoneId, ReportRainfallRequest request) {
505	        repository.findZoneByIdForUpdate(zoneId).orElseThrow(
506	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
507	        LocalDateTime hour = request.hourStart();
508	        if (!hour.equals(hour.truncatedTo(ChronoUnit.HOURS))) {
509	            throw ApiException.badRequest("RAINFALL_HOUR_NOT_ALIGNED",
510	                    "雨量小时起点须为UTC整点: " + hour);
511	        }
512	        requireFinite(request.rainfallMm(), "rainfallMm");
513	        var existing = repository.findRainfall(zoneId, hour);
514	        if (existing.isEmpty()) {
515	            if (request.expectedVersion() != 0) {
516	                throw ApiException.conflict("VERSION_CONFLICT",
517	                        "雨量记录不存在，首次上报expectedVersion须为0: " + request.expectedVersion());
518	            }
519	            long rainfallId = repository.insertRainfall(zoneId, hour, request.rainfallMm());
520	            return json(201, new RainfallResponse(rainfallId, zoneId, hour, request.rainfallMm(),
521	                    1, false, false));
522	        }
523	        RainfallRow row = existing.get();
524	        if (Double.compare(row.rainfallMm(), request.rainfallMm()) == 0) {
525	            // 同测区同小时同值重放：返回既有记录，不产生新版本。
526	            return json(200, new RainfallResponse(row.id(), zoneId, hour, row.rainfallMm(),
527	                    row.version(), true, false));
528	        }
529	        // 异值须显式更正版本：expectedVersion 等于当前版本才受理。
530	        if (request.expectedVersion() != row.version()) {
531	            throw ApiException.conflict("VERSION_CONFLICT",
532	                    "雨量更正版本冲突: expected=" + request.expectedVersion()
533	                            + ", current=" + row.version());
534	        }
535	        repository.updateRainfall(row.id(), request.rainfallMm(), row.version() + 1);
536	        return json(200, new RainfallResponse(row.id(), zoneId, hour, request.rainfallMm(),
537	                row.version() + 1, false, true));
538	    }
539	
540	    /**
541	     * 此前24个完整小时的雨量窗口：bucket 为 [floor(at)-24h, floor(at)) 的24个整点小时。
542	     * 任一缺点 complete=false 且 sum 为 null（缺失不得当零）。
543	     */
544	    private RainfallWindow rainfallWindow(long zoneId, LocalDateTime at) {
545	        LocalDateTime end = at.truncatedTo(ChronoUnit.HOURS);
546	        LocalDateTime start = end.minusHours(RAINFALL_WINDOW_HOURS);
547	        Map<LocalDateTime, Double> byHour = new HashMap<>();
548	        for (RainfallRow row : repository.findRainfallByZoneBetween(zoneId, start, end)) {
549	            byHour.put(row.hourStart(), row.rainfallMm());
550	        }
551	        List<LocalDateTime> missing = new ArrayList<>();
552	        double sum = 0.0;
553	        for (int i = 0; i < RAINFALL_WINDOW_HOURS; i++) {
554	            LocalDateTime bucket = start.plusHours(i);
555	            Double value = byHour.get(bucket);
556	            if (value == null) {
557	                missing.add(bucket);
558	            } else {
559	                sum += value;
560	            }
561	        }
562	        return new RainfallWindow(start, missing.isEmpty(), missing.isEmpty() ? sum : null, missing);
563	    }
564	
565	    private static void requireFinite(Double value, String field) {
566	        if (value == null || !Double.isFinite(value)) {
567	            throw ApiException.badRequest("NON_FINITE_VALUE", "数值须为有限值: " + field);
568	        }
569	    }
570	
571	    /** 雨量窗口：起点、是否完整、合计（不完整时为null）、缺点小时列表。 */
572	    private record RainfallWindow(LocalDateTime start, boolean complete, Double sum,
573	                                  List<LocalDateTime> missingHours) {
574	    }
575	
576	    /**
577	     * 复工安全评估：连续24小时按每个时刻实际有效的阈值判定。
578	     * 评估时刻存在生效策略版本时：读取此前24个完整小时雨量，任一缺点返回数据不足并
579	     * 阻断（不得当零）；雨量恰达门槛启用折减；速率恰等有效阈值仍判正常（须严格低于）。
580	     * 策略变严（黄/红阈值或折减系数变低）后安全计时自生效时刻重新累计，不沿用旧计时；
581	     * 变宽不影响既有处置链。无生效策略时回退测区静态安全线（旧线）。
582	     * 雨量与策略版本均取自本事务同一快照（调用方已持有测区行锁）。
583	     */
584	    private SafetyEvaluation evaluateResumptionSafety(ChainRow chain, ZoneRow zone,
585	                                                      LocalDateTime evaluatedAt) {
586	        List<StrategyRow> strategies = repository.findStrategiesByZone(chain.zoneId());
587	        StrategyRow atEval = strategies.stream()
588	                .filter(s -> !s.effectiveFrom().isAfter(evaluatedAt))
589	                .max((a, b) -> a.effectiveFrom().equals(b.effectiveFrom())
590	                        ? Integer.compare(a.version(), b.version())
591	                        : a.effectiveFrom().compareTo(b.effectiveFrom()))
592	                .orElse(null);
593	
594	        LocalDateTime windowStart = chain.triggeredAt();
595	        LocalDateTime rainfallStart = null;
596	        Double rainfallSum = null;
597	        boolean reduction = false;
598	        Integer strategyVersion = null;
599	        double evalThreshold = zone.safetyHourlyRate();
600	
601	        if (atEval != null) {
602	            strategyVersion = atEval.version();
603	            RainfallWindow rainfall = rainfallWindow(chain.zoneId(), evaluatedAt);
604	            if (!rainfall.complete()) {
605	                throw ApiException.unprocessable("RAINFALL_DATA_INSUFFICIENT",
606	                        "此前24个完整小时雨量数据不足，阻断复工批准: firstMissing="
607	                                + rainfall.missingHours().get(0));
608	            }
609	            rainfallStart = rainfall.start();
610	            rainfallSum = rainfall.sum();
611	            // 雨量恰达门槛即启用折减。
612	            reduction = rainfallSum >= atEval.rainfall24hThreshold();
613	            evalThreshold = atEval.yellowRate() * (reduction ? atEval.reductionFactor() : 1.0);
614	            // 策略变严后不沿用旧安全计时：自最新变严版本生效时刻重新累计。
615	            LocalDateTime stricterAt = latestStricterBoundary(strategies, evaluatedAt);
616	            if (stricterAt != null && stricterAt.isAfter(windowStart)) {
617	                windowStart = stricterAt;
618	            }
619	            if (evaluatedAt.isBefore(windowStart.plusHours(RECOVERY_WINDOW_HOURS))) {
620	                throw ApiException.unprocessable("SAFETY_WINDOW_RESTARTED",
621	                        "策略变严后安全计时重新累计，生效后未满24小时: earliest="
622	                                + windowStart.plusHours(RECOVERY_WINDOW_HOURS));
623	            }
624	        }
625	
626	        final LocalDateTime start = windowStart;
627	        List<ReadingRow> window = repository.findReadingsByZone(chain.zoneId()).stream()
628	                .filter(row -> row.measuredAt().isAfter(start)
629	                        && !row.measuredAt().isAfter(evaluatedAt))
630	                .toList();
631	        if (window.isEmpty()) {
632	            throw ApiException.unprocessable("NO_MONITORING_DATA",
633	                    "预警后窗口内无监测数据，无法证明速率回落: " + chain.id());
634	        }
635	        var detail = objectMapper.createObjectNode();
636	        detail.put("evaluatedAt", evaluatedAt.toString());
637	        detail.put("windowStart", windowStart.toString());
638	        var readingsNode = detail.putArray("readings");
639	        for (ReadingRow row : window) {
640	            // 每个时刻实际有效的阈值：该时刻生效的策略版本（无则旧线），叠加评估时的折减判定。
641	            double threshold = zone.safetyHourlyRate();
642	            Integer rowVersion = null;
643	            if (atEval != null) {
644	                StrategyRow atReading = strategies.stream()
645	                        .filter(s -> !s.effectiveFrom().isAfter(row.measuredAt()))
646	                        .max((a, b) -> a.effectiveFrom().equals(b.effectiveFrom())
647	                                ? Integer.compare(a.version(), b.version())
648	                                : a.effectiveFrom().compareTo(b.effectiveFrom()))
649	                        .orElse(null);
650	                if (atReading != null) {
651	                    rowVersion = atReading.version();
652	                    threshold = atReading.yellowRate()
653	                            * (reduction ? atReading.reductionFactor() : 1.0);
654	                }
655	            }
656	            // 速率恰等有效阈值判正常：仅严格低于才安全。
657	            if (row.hourlyRate() == null || row.hourlyRate() >= threshold) {
658	                throw ApiException.unprocessable("RATE_ABOVE_SAFETY_LINE",
659	                        "窗口内存在速率未回落至有效安全阈值以下的读数: measuredAt="
660	                                + row.measuredAt() + ", threshold=" + threshold);
661	            }
662	            var item = readingsNode.addObject();
663	            item.put("measuredAt", row.measuredAt().toString());
664	            item.put("hourlyRate", row.hourlyRate());
665	            if (rowVersion != null) {
666	                item.put("strategyVersion", rowVersion);
667	            }
668	            item.put("threshold", threshold);
669	            item.put("passed", true);
670	        }
671	        String detailJson;
672	        try {
673	            detailJson = objectMapper.writeValueAsString(detail);
674	        } catch (Exception e) {
675	            throw new IllegalStateException("证据明细序列化失败", e);
676	        }
677	        return new SafetyEvaluation(windowStart, evaluatedAt, rainfallStart, rainfallSum,
678	                reduction, strategyVersion, evalThreshold, window.size(), detailJson);
679	    }
680	
681	    /** 最新变严版本的生效时刻（不晚于评估时刻）；无变严版本时为 null。 */
682	    private LocalDateTime latestStricterBoundary(List<StrategyRow> strategies,
683	                                                 LocalDateTime evaluatedAt) {
684	        LocalDateTime boundary = null;
685	        for (int i = 1; i < strategies.size(); i++) {
686	            StrategyRow prev = strategies.get(i - 1);
687	            StrategyRow current = strategies.get(i);
688	            boolean stricter = current.yellowRate() < prev.yellowRate()
689	                    || current.redRate() < prev.redRate()
690	                    || current.reductionFactor() < prev.reductionFactor();
691	            if (stricter && !current.effectiveFrom().isAfter(evaluatedAt)
692	                    && (boundary == null || current.effectiveFrom().isAfter(boundary))) {
693	                boundary = current.effectiveFrom();
694	            }
695	        }
696	        return boundary;
697	    }
698	
699	    private void insertEvidence(long chainId, long assessmentId, long zoneId,
700	                                LocalDateTime evaluatedAt, SafetyEvaluation evaluation) {
701	        repository.insertEvidence(chainId, assessmentId, zoneId, evaluatedAt,
702	                evaluation.windowStart(), evaluation.windowEnd(), evaluation.rainfallWindowStart(),
703	                evaluation.rainfall24hSum(), evaluation.reductionApplied(),
704	                evaluation.strategyVersion(), evaluation.safetyThreshold(),
705	                evaluation.readingCount(), evaluation.detail());
706	    }
707	
708	    /** 一次复工安全评估的冻结结果。 */
709	    private record SafetyEvaluation(LocalDateTime windowStart, LocalDateTime windowEnd,
710	                                    LocalDateTime rainfallWindowStart, Double rainfall24hSum,
711	                                    boolean reductionApplied, Integer strategyVersion,
712	                                    double safetyThreshold, int readingCount, String detail) {
713	    }
714	
715	    /** 幂等指纹携带路径参数，避免不同测区/链的同requestId互相重放。 */
716	    record ZoneScopedRequest<T>(long zoneId, T body) {
717	    }
718	
719	    /** 幂等指纹携带路径参数，避免不同测区/链的同requestId互相重放。 */
720	    record ChainScopedRequest<T>(long chainId, T body) {
721	    }
722	}
